using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
namespace AnimalArchive {
 public class ArkCreature {
  public int id;public Transform root,body;public Transform[] legs;public Vector3 rest;public float happyUntil;public Vector2 wander;public float nextWander;public int activity;public float activityUntil;
  public void Pose(float time,bool walk){float f=walk?11:1.9f;body.localPosition=new Vector3(0,Mathf.Sin(time*f+id)* (walk?.055f:.018f),0);body.localRotation=Quaternion.Euler(0,0,Mathf.Sin(time*f*.5f+id)*(walk?2:1));for(int i=0;i<legs.Length;i++)legs[i].localRotation=Quaternion.Euler(walk?Mathf.Sin(time*f+(i%2)*Mathf.PI)*24:0,0,0);if(time<activityUntil&&!walk){body.localRotation=Quaternion.Euler(activity==1?10+Mathf.Sin(time*7)*7:0,0,activity==2?Mathf.Sin(time*8)*6:0);}if(time<happyUntil)body.localPosition+=Vector3.up*Mathf.Abs(Mathf.Sin(time*8))*.22f;}
 }
 public class ArkWorld:MonoBehaviour {
  public Camera cam;public Transform scenery;public List<ArkCreature> animals=new List<ArkCreature>();public Transform barrier,plate,food,toy;public LineRenderer route;public int mood;public bool room;public float pulse;public Vector3 focus=new Vector3(0,0,.2f);
  static Dictionary<Color,Material> mats=new Dictionary<Color,Material>();static Mesh orb,box,cylinder;public static Color Ink=C("302B43"),Cream=C("EFE1BD"),Gold=C("D9A94E"),Terracotta=C("B75C42"),Teal=C("567F79");
  List<Transform> waves=new List<Transform>();Vector2 sway;float camZoom=1;public float Zoom {set{camZoom=value;}}
  public static Color C(string s){ColorUtility.TryParseHtmlString("#"+s,out var c);return c;}
  void Awake(){cam=new GameObject("Ark Camera").AddComponent<Camera>();cam.tag="MainCamera";cam.orthographic=true;cam.nearClipPlane=.1f;cam.farClipPlane=150;cam.clearFlags=CameraClearFlags.SolidColor;cam.gameObject.AddComponent<AudioListener>();}
  public static Material Mat(Color c){if(!mats.TryGetValue(c,out var m)){m=new Material(Resources.Load<Shader>("Shaders/Ark"));m.color=c;mats.Add(c,m);}return m;}
  static Mesh Flat(List<Vector3> v,List<int> idx){var a=new Vector3[idx.Count];for(int i=0;i<a.Length;i++)a[i]=v[idx[i]];var m=new Mesh();m.vertices=a;m.triangles=Enumerable.Range(0,a.Length).ToArray();m.RecalculateNormals();m.RecalculateBounds();return m;}
  static Mesh Ball(){var v=new List<Vector3>();var t=new List<int>();int rings=6,slices=10;for(int y=0;y<=rings;y++){float a=Mathf.PI*y/rings;for(int x=0;x<slices;x++){float b=2*Mathf.PI*x/slices;v.Add(new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Cos(a),Mathf.Sin(a)*Mathf.Sin(b))*.5f);}}for(int y=0;y<rings;y++)for(int x=0;x<slices;x++){int a=y*slices+x,b=y*slices+(x+1)%slices;t.AddRange(new[]{a,a+slices,b,b,a+slices,b+slices});}t.Reverse();return Flat(v,t);}
  static Mesh Cube(){var v=new List<Vector3>{new Vector3(-.5f,-.5f,-.5f),new Vector3(.5f,-.5f,-.5f),new Vector3(.5f,.5f,-.5f),new Vector3(-.5f,.5f,-.5f),new Vector3(-.5f,-.5f,.5f),new Vector3(.5f,-.5f,.5f),new Vector3(.5f,.5f,.5f),new Vector3(-.5f,.5f,.5f)};return Flat(v,new List<int>{0,3,2,0,2,1,1,2,6,1,6,5,5,6,7,5,7,4,4,7,3,4,3,0,3,7,6,3,6,2,4,0,1,4,1,5});}
  static Mesh Disc(){var v=new List<Vector3>();var t=new List<int>();for(int y=0;y<2;y++)for(int i=0;i<16;i++){float a=i*Mathf.PI/8;v.Add(new Vector3(Mathf.Cos(a)*.5f,y-.5f,Mathf.Sin(a)*.5f));}v.Add(new Vector3(0,.5f,0));for(int i=0;i<16;i++){int n=(i+1)%16;t.AddRange(new[]{i,n,i+16,n,n+16,i+16,32,i+16,n+16});}t.Reverse();return Flat(v,t);}
  public static Transform Part(Transform parent,string name,Vector3 pos,Vector3 size,Color color,int shape=0){if(orb==null){orb=Ball();box=Cube();cylinder=Disc();}var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.AddComponent<MeshFilter>().sharedMesh=shape==1?orb:shape==2?cylinder:box;g.AddComponent<MeshRenderer>().sharedMaterial=Mat(color);return g.transform;}
  public static void Batch(Transform parent){var renderers=parent.GetComponentsInChildren<MeshRenderer>();foreach(var group in renderers.GroupBy(x=>x.sharedMaterial)){var combines=group.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=parent.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh();mesh.CombineMeshes(combines);var g=new GameObject("Pigment mesh");g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=group.Key;}foreach(var r in renderers)Destroy(r.gameObject);}
  public ArkCreature Creature(int id,Vector2 pos,float size=1,Transform parent=null){var root=new GameObject("Animal "+id).transform;root.SetParent(parent==null?scenery:parent,false);root.localPosition=new Vector3(pos.x,.08f,pos.y);root.localScale=Vector3.one*size;var body=new GameObject("Breathing rig").transform;body.SetParent(root,false);
   Color[] colors={C("D29656"),Cream,C("CC6940"),C("E3D9C5"),C("977B62"),C("9C775A"),C("BF9160"),Ink,C("667D56"),Cream,C("817C74"),C("CDD1C4")};Color fur=colors[id];bool bird=id==4||id==7,turtle=id==8;float neck=id==6||id==9?.42f:0;
   Part(root,"Contact shadow",new Vector3(.13f,-.055f,.13f),new Vector3(1.05f,.02f,1.05f),C("756358"),2);
   Part(body,"Body",new Vector3(0,turtle?.35f:.58f,0),new Vector3(bird?.76f:.73f,turtle?.43f:bird?1.02f:.65f,bird?.62f:1.0f),fur,1);
   if(turtle){Part(body,"Shell",new Vector3(0,.52f,.05f),new Vector3(1.02f,.52f,1.15f),C("495A49"),1);for(int k=0;k<3;k++)Part(body,"Shell ridge",new Vector3(0,.74f,.3f-k*.26f),new Vector3(.32f,.08f,.2f),Gold,1);}
   if(neck>0)Part(body,"Neck",new Vector3(0,.86f,-.26f),new Vector3(.33f,.85f,.35f),fur,1);
   Vector3 head=new Vector3(0,turtle?.4f:bird?.97f:.89f+neck,turtle?-.53f:-.39f);Part(body,"Head",head,new Vector3(bird?.65f:.64f,bird?.54f:.59f,.57f),fur,1);
   Part(body,"Muzzle",head+new Vector3(0,-.13f,-.22f),new Vector3(.4f,.24f,.28f),id==10?Cream:bird?Gold:Cream,1);
   if(id==4)for(int s=-1;s<=1;s+=2)Part(body,"Facial disk",head+new Vector3(s*.16f,.02f,-.22f),new Vector3(.33f,.35f,.12f),Cream,1);
   if(id==10)for(int s=-1;s<=1;s+=2)Part(body,"Badger mask",head+new Vector3(s*.17f,.045f,-.24f),new Vector3(.13f,.4f,.07f),Ink);
   for(int s=-1;s<=1;s+=2){Part(body,"Eye",head+new Vector3(s*.16f,.045f,-.27f),new Vector3(.074f,.092f,.05f),Ink,1);Part(body,"Eye glint",head+new Vector3(s*.16f-.01f,.07f,-.297f),new Vector3(.022f,.024f,.012f),Cream,1);
    if(!bird&&!turtle){float eh=id==3?.66f:id==9?.36f:.27f;var ear=Part(body,"Ear",head+new Vector3(s*.23f,.27f+eh*.18f,0),new Vector3(id==1?.28f:.21f,eh,.19f),fur,1);ear.localRotation=Quaternion.Euler(0,0,s*(id==1?65:18));Part(body,"Ear inner",ear.localPosition+new Vector3(0,0,-.075f),new Vector3(.10f,eh*.65f,.03f),C("C6877E"),1);}
    if(bird)Part(body,"Wing",new Vector3(s*.38f,.57f,0),new Vector3(.18f,.68f,.48f),fur,1);
    if(id==6){var antler=Part(body,"Antler",head+new Vector3(s*.2f,.56f,.08f),new Vector3(.085f,.62f,.085f),Ink);antler.localRotation=Quaternion.Euler(0,0,-s*20);Part(body,"Antler tip",head+new Vector3(s*.32f,.69f,.08f),new Vector3(.32f,.075f,.08f),Ink);}
   }
   Part(body,"Nose",head+new Vector3(0,-.07f,bird?-.40f:-.365f),new Vector3(.105f,.08f,.08f),bird?Gold:Ink,1);
   if(id==7)Part(body,"White belly",new Vector3(0,.55f,-.29f),new Vector3(.5f,.69f,.12f),Cream,1);
   if(id==1||id==9){for(int i=0;i<8;i++){float a=i*Mathf.PI/4;Part(body,"Wool",new Vector3(Mathf.Cos(a)*.27f,.67f,Mathf.Sin(a)*.37f),new Vector3(.4f,.45f,.4f),Cream,1);}}
   if(id==2||id==11||id==0||id==5){var tail=Part(body,"Tail",new Vector3(.15f,.53f,.67f),new Vector3(id==2?.38f:.16f,.22f,id==2?.9f:.65f),fur,1);tail.localRotation=Quaternion.Euler(-22,22,0);if(id==2)Part(body,"Tail tip",new Vector3(.29f,.68f,.96f),new Vector3(.29f,.21f,.35f),Cream,1);}
   Part(body,"Ark scarf",new Vector3(0,.69f+neck,-.30f),new Vector3(.64f,.105f,.48f),id%2==0?Terracotta:Teal,2);
   Batch(body);var legs=new List<Transform>();for(int k=0;k<(bird?2:4);k++){float x=(k%2==0?-.25f:.25f),z=bird?-.02f:(k<2?-.29f:.29f);var leg=Part(root,"Walking leg",new Vector3(x,turtle?.16f:.22f,z),new Vector3(turtle?.26f:.15f,turtle?.16f:.35f,.21f),bird?Gold:fur,1);legs.Add(leg);}
   var c=new ArkCreature{id=id,root=root,body=body,legs=legs.ToArray(),rest=root.position,wander=pos,nextWander=Time.time+2+id*.35f};animals.Add(c);return c;
  }
  Transform Group(string name){var g=new GameObject(name).transform;g.SetParent(scenery,false);return g;}
  public void Clear(){if(scenery){foreach(var mf in scenery.GetComponentsInChildren<MeshFilter>())if(mf.sharedMesh!=orb&&mf.sharedMesh!=box&&mf.sharedMesh!=cylinder)Destroy(mf.sharedMesh);Destroy(scenery.gameObject);}scenery=new GameObject("Editable Ark world").transform;animals.Clear();waves.Clear();barrier=plate=food=toy=null;route=null;}
  void Block(Transform p,Vector3 at,Vector3 size,Color c){Part(p,"Ink plinth",at-new Vector3(0,.045f,0),size+new Vector3(.07f,.03f,.07f),Ink);Part(p,"Plaster",at,size,c);}
  void Arch(Transform p,Vector3 at,float width,float height,Color c){float r=width/2,h=height-r;
   for(int side=-1;side<=1;side+=2)Block(p,at+new Vector3(side*(r+.12f),h/2,0),new Vector3(.28f,h,.38f),c);
   for(int i=0;i<12;i++){float angle=(i+.5f)*Mathf.PI/12;var t=Part(p,"Arch voussoir",at+new Vector3(Mathf.Cos(angle)*(r+.12f),h+Mathf.Sin(angle)*(r+.12f),0),new Vector3(.30f,(r+.25f)*Mathf.PI/12+.04f,.42f),c);t.localRotation=Quaternion.Euler(0,0,angle*Mathf.Rad2Deg);}
   var v=new List<Vector3>{new Vector3(-r,0,0),new Vector3(r,0,0)};for(int i=0;i<=16;i++){float a=i*Mathf.PI/16;v.Add(new Vector3(Mathf.Cos(a)*r,h+Mathf.Sin(a)*r,0));}var idx=new List<int>();for(int i=1;i<v.Count-1;i++)idx.AddRange(new[]{0,i+1,i});var g=new GameObject("Arched recess");g.transform.SetParent(p,false);g.transform.localPosition=at+Vector3.forward*.2f;g.AddComponent<MeshFilter>().sharedMesh=Flat(v,idx);g.AddComponent<MeshRenderer>().sharedMaterial=Mat(Ink);
  }
  public void Build(int chapter,ArkStage stage=null,bool garden=false){Clear();mood=chapter;room=garden;camZoom=1;focus=new Vector3(0,0,.3f);cam.backgroundColor=chapter==0?C("DBBE89"):chapter==1?C("A3B6AB"):C("58546D");var env=Group("Architecture");Color plaster=chapter==0?Cream:chapter==1?C("C7CDC0"):C("C4AE9E");Color water=chapter==0?C("6B9192"):chapter==1?C("577D87"):C("4D586F");
   Part(env,"Sea to the horizon",new Vector3(0,-1.2f,0),new Vector3(180,.15f,180),water);
   for(int i=0;i<32;i++){float x=(i%8-3.5f)*4.5f,z=(i/8-1.2f)*7.7f;var w=Part(scenery,"Water glint",new Vector3(x,-1.06f,z),new Vector3(1.3f+(i%3)*.8f,.018f,.075f),chapter==2?C("77838E"):C("B5C4AD"));waves.Add(w);}
   // Raised continuous floor, deep vertical sides and architectural silhouettes.
   Block(env,new Vector3(0,-.62f,.05f),new Vector3(10.35f,1.2f,11.4f),chapter==0?C("CC985C"):Terracotta);
   Part(env,"Continuous limestone surface",new Vector3(0,.005f,.05f),new Vector3(10.28f,.08f,11.35f),garden?C("CDBF93"):plaster);
   for(int i=0;i<7;i++){Part(env,"Deck edge brass",new Vector3(-4.96f,.08f,-4.8f+i*1.65f),new Vector3(.12f,.055f,1.25f),Gold);Part(env,"Deck edge brass",new Vector3(4.96f,.08f,-4.8f+i*1.65f),new Vector3(.12f,.055f,1.25f),Gold);}
   for(int i=0;i<5;i++){float x=-10+i*5.5f,z=10+(i%2)*4;float h=4+(i%3)*2;Block(env,new Vector3(x,h/2-1,z),new Vector3(3.1f,h,3.2f),i%2==0?Terracotta:C("B7A273"));Arch(env,new Vector3(x,-.5f,z-1.64f),1.3f,2.4f,Cream);for(int k=0;k<3;k++)Part(env,"Tower slit",new Vector3(x-1+k,.7f+h*.4f,z-1.66f),new Vector3(.24f,1,.12f),Ink);}
   // Boat hull beyond the evacuation piers.
   Block(env,new Vector3(0,-.15f,6.9f),new Vector3(9.7f,.7f,2.5f),C("7B5343"));Block(env,new Vector3(0,.3f,7.8f),new Vector3(8.8f,1,1.05f),Terracotta);for(int k=-1;k<=1;k++)Arch(env,new Vector3(k*2.8f,.15f,7.15f),1.55f,2.1f,Gold);
   for(int side=-1;side<=1;side+=2){var roof=Part(env,"Ark pitched roof",new Vector3(0,2.75f,7.85f+side*.66f),new Vector3(9.9f,.18f,1.65f),Terracotta);roof.localRotation=Quaternion.Euler(side*32,0,0);}Part(env,"Roof ridge",new Vector3(0,3.22f,7.85f),new Vector3(10.05f,.15f,.18f),Gold);
   Part(env,"Mast",new Vector3(3.9f,3.25f,7.8f),new Vector3(.13f,6,.13f),Ink);Part(env,"Sail",new Vector3(2.35f,4.4f,7.8f),new Vector3(2.8f,2.5f,.09f),Cream);Part(env,"Sail emblem",new Vector3(2.35f,4.4f,7.73f),new Vector3(.18f,1.5f,.035f),Terracotta);
   if(stage!=null){foreach(var b in stage.blocks){if(b.kind=="barrier")continue;if(b.kind=="water"){Part(env,"Flooded courtyard",new Vector3(b.x,.067f,b.z),new Vector3(b.w,.06f,b.d),water);Part(env,"Broken edge",new Vector3(b.x,.1f,b.z-b.d/2),new Vector3(b.w,.14f,.13f),Ink);}else{Block(env,new Vector3(b.x,.55f,b.z),new Vector3(b.w,1.05f,b.d),chapter==0?C("D3AC71"):plaster);Part(env,"Masonry cap",new Vector3(b.x,1.1f,b.z),new Vector3(b.w+.14f,.11f,b.d+.14f),Cream);}}
    if(stage.lever){barrier=Group("Retractable storm barrier");foreach(var b in stage.blocks.Where(b=>b.kind=="barrier")){Block(barrier,new Vector3(b.x,.44f,b.z),new Vector3(b.w,.83f,b.d),Terracotta);for(int j=-4;j<=4;j++)Part(barrier,"Gate braces",new Vector3(j,.5f,b.z-.3f),new Vector3(.11f,1.2f,.1f),Gold);}Batch(barrier);plate=Part(scenery,"Bell pressure plate",new Vector3(stage.sx,.115f,stage.sz),new Vector3(1.15f,.16f,1.15f),Gold,2);}
    foreach(var a in stage.animals){Part(env,"Boarding pier",new Vector3(a.gx,.10f,5.04f),new Vector3(1.5f,.18f,2.3f),C("AC8159"));Part(env,"Berth carpet",new Vector3(a.gx,.2f,a.gz),new Vector3(1.35f,.045f,1.0f),a.id%2==0?Terracotta:Teal);for(int s=-1;s<=1;s+=2)Part(env,"Pier marker",new Vector3(a.gx+s*.65f,.54f,5.05f),new Vector3(.11f,.8f,.11f),Gold);}
   }else{for(int i=0;i<3;i++){Arch(env,new Vector3(-4.2f+i*4.2f,.1f,3.9f),2.2f,2.5f,plaster);}Part(env,"Woven resting carpet",new Vector3(.5f,.07f,-.3f),new Vector3(4.8f,.05f,3.8f),Terracotta);Part(env,"Carpet center",new Vector3(.5f,.1f,-.3f),new Vector3(4.25f,.03f,3.25f),C("C68860"));for(int i=0;i<4;i++){Part(env,"Cushion",new Vector3(-3.3f+i*2.1f,.23f,2.6f),new Vector3(1.25f,.35f,.8f),i%2==0?Teal:Gold,1);}food=Part(scenery,"Food bowl",new Vector3(-2.8f,.15f,-2),new Vector3(.9f,.28f,.9f),Gold,2);Part(food,"Seeds",new Vector3(0,.55f,0),new Vector3(.7f,.1f,.7f),C("85684C"),1);toy=Part(scenery,"Play ball",new Vector3(2.9f,.36f,-1.5f),Vector3.one*.75f,C("5795AB"),1);Part(toy,"Ball stripe",Vector3.zero,new Vector3(1.02f,.13f,1.02f),Cream,2);}
   if(chapter==0){for(int j=0;j<4;j++){float x=j%2==0?-4.55f:4.55f,z=-3.4f+(j/2)*5.4f;Part(env,"Terracotta planter",new Vector3(x,.28f,z),new Vector3(.54f,.52f,.54f),Terracotta,2);Part(env,"Olive foliage",new Vector3(x,.7f,z),new Vector3(.83f,.8f,.73f),Teal,1);}}
   if(chapter==1){for(int j=0;j<5;j++){float x=-7.3f+(j%2)*14.4f,z=-4+j*2.3f;Block(env,new Vector3(x,.45f,z),new Vector3(1.7f,2.5f,1.6f),Cream);for(int k=0;k<4;k++)Part(env,"Abandoned stone records",new Vector3(x,.1f+k*.44f,z-.87f),new Vector3(1.35f,.26f,.13f),Gold);}}
   if(chapter==2){for(int j=0;j<8;j++){float x=j%2==0?-6.1f:6.5f,z=-5+j*1.55f;var rock=Part(env,"Broken breakwater",new Vector3(x,-.28f,z),new Vector3(1.3f,1.5f,2),Ink,1);rock.localRotation=Quaternion.Euler(20,j*31,12);}var rain=new GameObject("Storm rain");rain.transform.SetParent(scenery,false);var v=new List<Vector3>();var ids=new List<int>();var rng=new System.Random(51);for(int j=0;j<100;j++){float x=(float)rng.NextDouble()*30-15,y=(float)rng.NextDouble()*22,z=(float)rng.NextDouble()*25-12;int k=v.Count;v.Add(new Vector3(x,y,z));v.Add(new Vector3(x+.055f,y,z));v.Add(new Vector3(x+.26f,y+.72f,z));ids.AddRange(new[]{k,k+1,k+2});}rain.AddComponent<MeshFilter>().sharedMesh=Flat(v,ids);rain.AddComponent<MeshRenderer>().sharedMaterial=new Material(Resources.Load<Shader>("Shaders/Rain"));}
   for(int i=0;i<5;i++){float x=i%2==0?-5.65f:5.7f,z=-4+i*2.1f;Part(env,"Cypress trunk",new Vector3(x,.5f,z),new Vector3(.12f,1.6f,.12f),Ink);Part(env,"Cypress crown",new Vector3(x,1.6f,z),new Vector3(.8f,2.1f,.85f),chapter==2?C("526664"):Teal,1);}Batch(env);
   var rg=new GameObject("Visible walking route");rg.transform.SetParent(scenery,false);route=rg.AddComponent<LineRenderer>();route.material=new Material(Resources.Load<Shader>("Shaders/Route"));route.widthMultiplier=.105f;route.numCapVertices=3;route.positionCount=0;
  }
  public void DrawRoute(List<Vector2> p){if(p==null){route.positionCount=0;return;}route.positionCount=p.Count;route.SetPositions(p.Select(v=>new Vector3(v.x,.18f,v.y)).ToArray());}
  public Vector2 Screen(Vector3 v){var p=cam.WorldToScreenPoint(v);return new Vector2(p.x,ScreenHeight-p.y);}static float ScreenHeight=>UnityEngine.Screen.height;
  public Vector2 Ground(Vector2 pixel){var ray=cam.ScreenPointToRay(new Vector3(pixel.x,UnityEngine.Screen.height-pixel.y));float t=-ray.origin.y/ray.direction.y;var p=ray.origin+ray.direction*t;return new Vector2(p.x,p.z);}
  public void CameraStep(Vector2 mouse,float scroll=0){camZoom=Mathf.Clamp(camZoom+scroll*.03f,.86f,1.12f);var target=new Vector2((mouse.x/UnityEngine.Screen.width-.5f)*.33f,(mouse.y/UnityEngine.Screen.height-.5f)*.2f);sway=Vector2.Lerp(sway,target,Time.deltaTime*1.6f);var at=focus+new Vector3(sway.x,Mathf.Sin(Time.time*.25f)*.06f,sway.y);cam.transform.position=at+new Vector3(1.4f+Mathf.Sin(Time.time*.16f)*.12f,17,-18);cam.transform.LookAt(at);cam.orthographicSize=Mathf.Max(8.7f,5.95f/cam.aspect)*camZoom;for(int i=0;i<waves.Count;i++){var p=waves[i].localPosition;p.x+=(Mathf.Sin(Time.time*.4f+i)*.002f);p.y=-1.06f+Mathf.Sin(Time.time*.6f+i)*.03f;waves[i].localPosition=p;}}
 }
